#include <cstdint>

int mouseX(std::int64_t lParam) { return static_cast<std::int16_t>(lParam & 0xFFFF); }
int mouseY(std::int64_t lParam) { return static_cast<std::int16_t>((lParam >> 16) & 0xFFFF); }
int repeatCount(std::int64_t lParam) { return static_cast<int>(lParam & 0xFFFF); }
int scanCode(std::int64_t lParam) { return static_cast<int>((lParam >> 16) & 0xFF); }
bool isRepeat(std::int64_t lParam) { return ((lParam >> 30) & 1) != 0; }
bool isKeyUp(std::int64_t lParam) { return ((lParam >> 31) & 1) != 0; }
int wheelSteps(std::uint64_t wParam) { return static_cast<std::int16_t>((wParam >> 16) & 0xFFFF) / 120; }

unitTests:
TEST("mouse position") { CHECK_EQ(mouseX(0x00C80064), 100); CHECK_EQ(mouseY(0x00C80064), 200); }
TEST("negative coordinates") { CHECK_EQ(mouseX(0x0000FFFF), -1); CHECK_EQ(mouseY(0xFFF60000), -10); }
TEST("the first key press") { CHECK_EQ(repeatCount(0x00150001), 1); CHECK_EQ(scanCode(0x00150001), 0x15); CHECK(!isRepeat(0x00150001)); CHECK(!isKeyUp(0x00150001)); }
TEST("an auto-repeat") { CHECK(isRepeat(0x40150001)); CHECK(!isKeyUp(0x40150001)); }
TEST("a key up") { CHECK(isKeyUp(0xC0150001)); CHECK(isRepeat(0xC0150001)); }
TEST("several repeats in one message") { CHECK_EQ(repeatCount(0x40390005), 5); CHECK_EQ(scanCode(0x40390005), 0x39); }
TEST("the wheel") { CHECK_EQ(wheelSteps(0x00780000), 1); CHECK_EQ(wheelSteps(0xFF880000), -1); CHECK_EQ(wheelSteps(0x00F00008), 2); }

